// 真實上稿時可填 officialUrl；示範資料導向相關官方搜尋，不冒用真實企業 ID。
window.DEMO_LINKS = (() => {
 const data=window.DEMO_DATA;
 const official=(value,type)=>{try{const u=new URL(value);return u.protocol==='https:'&&['www.1111.com.tw','1111.com.tw'].includes(u.hostname)&&new RegExp('^/'+type+'/[0-9]+/?$').test(u.pathname)?u.href:null;}catch{return null;}};
 const search=(type,params)=>'https://www.1111.com.tw/search/'+type+'?'+new URLSearchParams(params);
 return {
  job:j=>official(j.officialUrl,'job')||search('job',{d0:j.duty||data.mainSite.categoryCodes[j.category]||'160206'}),
  company:c=>official(c.officialUrl,'corp')||search('corp',{t0:data.mainSite.industryCodes[c.industry]||'111200'}),
  industryJobs:c=>search('job',{t0:data.mainSite.industryCodes[c.industry]||'111200'}),
  categoryJobs:category=>search('job',{d0:data.mainSite.categoryCodes[category]||'160206'})
 };
})();

